-- Four food references checked against cited Qur’an and Sahih texts.
-- Editorial record, independent scholarly/clinical review still pending.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('vinegar','vinegar','Vinegar in the Prophetic Food Reports','الخل','A narrated condiment, not a clinically established treatment','prophetic_medicine','ingredient','Sahih Muslim 2052a reports the Prophet ﷺ praising vinegar as a condiment during a meal. The report concerns ordinary food, and does not establish that medicinal vinegar preparations cure illness.','Source-based educational reference','vinegar, khall, khal, prophetic vinegar, vinegar benefits, apple cider vinegar','Religious source identified; modern efficacy and clinical safety not independently certified','editorial_draft','published','90');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('vinegar-s1','vinegar','What is documented','overview','Vinegar appears in a transmitted food report rather than in a modern clinical treatment protocol. It should be classified as a narrated condiment, not a guaranteed healing intervention.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('vinegar-s2','vinegar','The transmitted meal','transmission','Sahih Muslim 2052a reports that when the Prophet ﷺ asked his household for a condiment, they had vinegar. He used it with food and spoke positively of it as a condiment. The precise report, context and translation should be checked against the cited source.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('vinegar-s3','vinegar','Food identity and varieties','historical','Vinegar can be produced from different food materials. A present-day bottle may differ in acidity, additives and intended use from historical preparations. A textual mention cannot authenticate every product marketed with a Prophetic label.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('vinegar-s4','vinegar','Medical evidence is separate','science','Claims that vinegar treats diabetes, infections or other diseases require condition-specific medical evidence. The narration itself does not state a therapeutic dose, controlled outcome or modern safety threshold.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('vinegar-s5','vinegar','Everyday precautions','safety','Highly acidic vinegar can irritate the mouth, throat or stomach, and concentrated products may damage tissue. People with medical conditions or taking medications should consult a qualified clinician before attempting concentrated medicinal use.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('vinegar-r1','vinegar','hadith','Sahih Muslim — The virtue of vinegar as a condiment','2052a','https://sunnah.com/muslim:2052a','pending','1');
INSERT OR IGNORE INTO encyclopedia_links(id,article_id,target_article_id,relation_label,sort_order) VALUES('vinegar--traditional-remedies-safety','vinegar','traditional-remedies-safety','Evidence and interpretation context','20');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('gourd-prophetic-food','gourd-prophetic-food','Gourd in a Prophetic Meal','الدباء','Reported food preference and the limits of medicinal inference','prophetic_medicine','ingredient','Sahih al-Bukhari 5436 describes a meal of barley bread and soup containing gourd and cured meat, and Anas observing the Prophet ﷺ choosing pieces of gourd. The report records a food preference, not a specific medicinal prescription.','Source-based educational reference','gourd, pumpkin, squash, dubba, prophetic pumpkin, calabash','Religious source identified; modern efficacy and clinical safety not independently certified','editorial_draft','published','90');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('gourd-prophetic-food-s1','gourd-prophetic-food','A food report, not a remedy order','overview','The chapter belongs to descriptions of food and daily life. The report can inform history and culinary tradition while remaining distinct from evidence that gourd treats a particular medical condition.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('gourd-prophetic-food-s2','gourd-prophetic-food','The tailor’s invitation','transmission','Sahih al-Bukhari 5436 narrates that a tailor invited the Prophet ﷺ to a meal. Anas accompanied him and observed a dish containing gourd and cured meat alongside barley bread. Anas said that the incident shaped his own fondness for gourd.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('gourd-prophetic-food-s3','gourd-prophetic-food','What the word identifies','historical','The Arabic term dubba is commonly rendered gourd in the cited translation. Modern plant labels vary by region; identifying the historical botanical species confidently requires further source and linguistic assessment.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('gourd-prophetic-food-s4','gourd-prophetic-food','Nutrition and claims','science','Gourd and related vegetables are ordinary foods. This report does not establish a universal therapeutic benefit, nor can a commercial gourd supplement inherit a claim of medical efficacy from the historical account.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('gourd-prophetic-food-s5','gourd-prophetic-food','Responsible application','safety','Food suitability depends on preparation and individual health circumstances. Avoid presenting unfamiliar concentrated extracts or advertised cures as religiously approved medicine.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('gourd-prophetic-food-r1','gourd-prophetic-food','hadith','Sahih al-Bukhari — Soup and the gourd','5436','https://sunnah.com/bukhari:5436','pending','1');
INSERT OR IGNORE INTO encyclopedia_links(id,article_id,target_article_id,relation_label,sort_order) VALUES('gourd-prophetic-food--traditional-remedies-safety','gourd-prophetic-food','traditional-remedies-safety','Evidence and interpretation context','20');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('cucumber-fresh-dates','cucumber-fresh-dates','Cucumber and Fresh Dates in the Sunnah','القثاء والرطب','A documented combination in everyday Prophetic food','prophetic_medicine','ingredient','Sahih al-Bukhari 5440 records Abdullah ibn Ja''far saying he saw the Prophet ﷺ eat fresh dates with snake cucumber. The food pairing is a source-linked historical observation, not proof of a medical treatment.','Source-based educational reference','cucumber and dates, fresh dates, qiththa, rutab, snake cucumber, date cucumber, prophetic diet','Religious source identified; modern efficacy and clinical safety not independently certified','editorial_draft','published','90');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('cucumber-fresh-dates-s1','cucumber-fresh-dates','An observed everyday food','overview','It is important to distinguish reports about what the Prophet ﷺ ate from medical directives. This report records an observed food pairing and should be approached in its food and historical context.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('cucumber-fresh-dates-s2','cucumber-fresh-dates','The report and its source','transmission','Sahih al-Bukhari 5440 preserves Abdullah ibn Ja''far’s observation concerning fresh dates and snake cucumber. Related narrations occur in the same food chapters; the exact terms and translation should be reviewed before assuming the identity of every modern cucumber variety.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('cucumber-fresh-dates-s3','cucumber-fresh-dates','Historical and botanical caution','historical','Fresh dates are known by the Arabic word rutab and the item translated as snake cucumber by qiththa. Modern botanical and local names vary. The narration is not a complete dietary instruction.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('cucumber-fresh-dates-s4','cucumber-fresh-dates','Do not invent a health mechanism','science','Claims that the combination balances body heat, cures a named illness or produces a measured medical effect require independent evidence. Those claims should not be attributed to the hadith unless directly supported and reviewed.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('cucumber-fresh-dates-s5','cucumber-fresh-dates','Individual considerations','safety','Fresh dates contain carbohydrates. People who monitor glucose or have specific dietary needs should account for their own healthcare guidance rather than treating this report as a prescribed diet.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('cucumber-fresh-dates-r1','cucumber-fresh-dates','hadith','Sahih al-Bukhari — Fresh dates with snake cucumber','5440','https://sunnah.com/bukhari:5440','pending','1');
INSERT OR IGNORE INTO encyclopedia_links(id,article_id,target_article_id,relation_label,sort_order) VALUES('cucumber-fresh-dates--traditional-remedies-safety','cucumber-fresh-dates','traditional-remedies-safety','Evidence and interpretation context','20');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('ginger-quranic-description','ginger-quranic-description','Ginger in Qur’anic Description','الزنجبيل','Zanjabil in Qur’an 76:17 and the difference between scripture and clinical research','prophetic_medicine','ingredient','Qur’an 76:17 mentions a drink whose mixture is zanjabil in a description of Paradise. This is scriptural imagery and does not constitute a medical prescription for ginger products in everyday life.','Source-based educational reference','ginger, zanjabil, zanjabeel, ginger in quran, prophetic ginger, ginger remedy','Religious source identified; modern efficacy and clinical safety not independently certified','editorial_draft','published','90');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ginger-quranic-description-s1','ginger-quranic-description','Read the verse in its setting','overview','The term zanjabil appears within Qur’anic description of the rewards of Paradise. Pulling a food name out of the passage and presenting it as a treatment rule changes the character of the source.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ginger-quranic-description-s2','ginger-quranic-description','The primary reference','scripture','Qur’an 76:17 describes a drink mixed with zanjabil. Major English translations render the word as ginger. The surrounding verses concern the next life, not the diagnosis or treatment of an illness in this life.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ginger-quranic-description-s3','ginger-quranic-description','Distinguish texts and later traditions','interpretation','A Qur’anic mention and a separate Hadith about the use of a food are different classes of evidence. This article does not assert a specific Prophetic medicinal instruction for ginger without an independently authenticated report.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ginger-quranic-description-s4','ginger-quranic-description','Research belongs to a separate layer','science','Modern evidence on ginger preparations may address particular symptoms or outcomes, but cannot be assumed to derive from Qur’an 76:17. Formulation, dose and population matter for any clinical claim.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('ginger-quranic-description-s5','ginger-quranic-description','Safety and product integrity','safety','Concentrated ginger supplements can have side effects or medication interactions. Avoid marketing a ginger retail product as clinically proven or religiously mandated merely because the term appears in scripture.','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('ginger-quranic-description-r1','ginger-quranic-description','quran','Qur’an — Surah al-Insan','76:17','https://quran.com/76/17','pending','1');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('ginger-quranic-description-r2','ginger-quranic-description','reference','Quranic Arabic Corpus — Zanjabil in Qur’an 76:17','Parallel translation reference','https://corpus.quran.com/translation.jsp?chapter=76&verse=17','pending','2');
INSERT OR IGNORE INTO encyclopedia_links(id,article_id,target_article_id,relation_label,sort_order) VALUES('ginger-quranic-description--healing-shifa','ginger-quranic-description','healing-shifa','Evidence and interpretation context','20');
